logger = logging.getLogger(__name__)


def _get_prod_api_config() -> tuple[dict[str, str], str]:
    """Laedt Header und Basis-URL fuer die produktive eSuite-API."""
    api_config = get_esuite_api_config("PROD")
    return api_config.headers, api_config.resthost


def accountbereinigung() -> bool:
    """Bereinigt die Account-Parameter (VkOrg, ZActive) über die eSuite API.

    Ruft die Stored Procedure 'Update_tb_accountbereinigung' auf, liest die zu
    bereinigenden Accounts und sendet PATCH-Requests an die eSuite API.

    Returns:
        True bei Erfolg, False bei Fehler.
    """
    logger.info("Starte accountbereinigung...")
    connection = None
    cursor = None
    try:
        connection = connect_to_db()
        cursor = connection.cursor()

        cursor.callproc("Update_tb_accountbereinigung")
        connection.commit()

        cursor.execute("SELECT * FROM tb_accountbereinigung ")
        result = cursor.fetchall()

        df = pd.DataFrame(result)
        headers, resthost = _get_prod_api_config()
        url_base = resthost + "accounts/"

        for _index, row in iter_with_progress(logger, df.iterrows(), len(df), "Accountbereinigung"):
            time.sleep(0.01)
            accountid = str(row[0])
            VKORG_SOLL = str(row[1])
            url = url_base + accountid
            data = [
                {"op": "replace", "path": "/CustomAccountParameter/VkOrg", "value": VKORG_SOLL},
                {"op": "replace", "path": "/CustomAccountParameter/ZActive", "value": "Ja"},
            ]
            json_data = json.dumps(data)

            try:
                response = retry_request("PATCH", url, data=json_data, headers=headers, verify=False)
                if response is None:
                    logger.error(f"Keine Antwort für Account {accountid}, überspringe.")
                    continue
                response.raise_for_status()
            except requests.exceptions.RequestException as e:
                logger.error(f"Request failed for account {accountid}: {str(e)}", exc_info=True)
                raise

        logger.info("accountbereinigung erfolgreich abgeschlossen")
        return True

    except mariadb.Error as e:
        logger.error(f"Fehler bei der Ausführung der Stored Procedure oder bei der Abfrage: {e}", exc_info=True)
        raise
    finally:
        if cursor:
            cursor.close()
        if connection:
            connection.close()


def accountbereinigung_2() -> bool:
    """Bereinigt Account-Parameter basierend auf SQL-Query statt Stored Procedure.

    Berechnet die VkOrg-Soll-Werte aus Order- und Account-VkOrg-Daten und
    sendet PATCH-Requests an die eSuite API.

    Returns:
        True bei Erfolg, False bei Fehler.
    """
    logger.info("Starte accountbereinigung...")
    try:
        df = execute_dataframe_query(get_query_text("ACCOUNTBEREINIGUNG_ESUITE"))

        if df.empty:
            logger.info("Keine Accounts für Bereinigung gefunden.")
            return True

        def build_vkorg_soll(row: pd.Series[Any]) -> set[Any]:
            """Ermittelt die Soll-Verkaufsorganisationen aus Order- und Account-Werten."""
            order_vals = {row["ORDER_VKORG"]} if row["ORDER_VKORG"] not in ("", "leer") else set()
            account_vals = set()
            if row["ACCOUNT_VKORG"] not in ("", "leer"):
                account_vals = {v.strip() for v in row["ACCOUNT_VKORG"].split(";") if v.strip() not in ("", "leer")}
            return order_vals | account_vals

        df["vals"] = df.apply(build_vkorg_soll, axis=1)
        result = df.groupby("ACCOUNTID")["vals"].agg(lambda x: ";".join(sorted(set.union(*x)))).reset_index()
        result.columns = ["ACCOUNTID", "VKORG_SOLL"]

        headers, resthost = _get_prod_api_config()
        url_base = resthost + "accounts/"

        for _index, row in iter_with_progress(logger, result.iterrows(), len(result), "Accountbereinigung"):
            time.sleep(0.01)
            accountid = str(row["ACCOUNTID"])
            vkorg_soll = str(row["VKORG_SOLL"])
            url = url_base + accountid
            data = [
                {"op": "replace", "path": "/CustomAccountParameter/VkOrg", "value": vkorg_soll},
                {"op": "replace", "path": "/CustomAccountParameter/ZActive", "value": "Ja"},
            ]

            try:
                response = retry_request("PATCH", url, data=json.dumps(data), headers=headers, verify=False)
                if response is None:
                    logger.error(f"Request für Account {accountid} nach allen Versuchen fehlgeschlagen, überspringe.")
                    continue
                response.raise_for_status()
            except requests.exceptions.RequestException as e:
                logger.error(f"Request failed for account {accountid}: {str(e)}")

        logger.info("accountbereinigung erfolgreich abgeschlossen")
        return True

    except Exception as e:
        logger.error(f"Fehler bei der Ausführung der Abfrage: {e}", exc_info=True)
        raise


def subscriptionbereinigung(database: str = DATABASE) -> bool:
    """Storniert Subscriptions über die eSuite API per PATCH-Request.

    Lädt die zu stornierenden Subscriptions aus der Datenbank und setzt
    deren status auf 'cancelledByCustomerSupport'.

    Args:
        database: Der Name der Datenbank, in der die Bereinigung durchgeführt werden soll.

    Returns:
        True bei Erfolg, False bei Fehler.
    """
    logger.info("Starte subscriptionbereinigung...")
    connection = None
    cursor = None
    try:
        connection = connect_to_db(database)
        cursor = connection.cursor()

        query_text = get_query_text("SUBSCRIPTION_BEREINIGUNG")

        cursor.execute(query_text)
        result = cursor.fetchall()

        df = pd.DataFrame(result)
        headers, resthost = _get_prod_api_config()

        for _index, row in iter_with_progress(logger, df.iterrows(), len(df), "Subscriptionbereinigung"):
            time.sleep(0.01)
            accountid = str(row[0])
            subscriptionid = str(row[1])
            url = resthost + "accounts/" + accountid + "/subscriptions/" + subscriptionid
            data = [{"op": "replace", "path": "/status", "value": "cancelledByCustomerSupport"}]
            json_data = json.dumps(data)

            try:
                response = retry_request("PATCH", url, data=json_data, headers=headers, verify=False)
                if response is None:
                    logger.error(f"Request für Account {accountid} nach allen Versuchen fehlgeschlagen, überspringe.")
                    continue
                response.raise_for_status()
            except requests.exceptions.RequestException as e:
                logger.error(f"Request failed for account {accountid}: {str(e)}")

        logger.info("subscriptionbereinigung erfolgreich abgeschlossen")
        return True
    except mariadb.Error as e:
        logger.error(f"Fehler bei der Ausführung der Stored Procedure oder bei der Abfrage: {e}", exc_info=True)
        raise
    finally:
        if cursor:
            cursor.close()
        if connection:
            connection.close()
        logger.info("subscriptionbereinigung abgeschlossen.")


def umstellabos() -> None:
    """Verarbeitet umstellabos aus Excel-Dateien und aktualisiert die eSuite API.

    Liest Excel-Dateien aus dem umstellabos-Verzeichnis, importiert sie in die
    Datenbank, aktualisiert die Subscription-Parameter per API und exportiert
    das Ergebnis als Prüfdatei.
    """
    logger.info("Starte Umstellabos Verarbeitung...")

    HEADERS = ["GPNR", "VBELN", "POSNR", "DATUM"]
    temp_csv = "temp_csv.csv"
    table = "tb_umstellabos"

    all_filenames = [f for f in os.listdir(UMSTELLABOS_PATH) if os.path.isfile(os.path.join(UMSTELLABOS_PATH, f))]
    matching_files = [f for f in all_filenames if re.match(r".*\.xlsx$", f) and not f.startswith("~$")]
    if not matching_files:
        logger.info("Keine Excel-Dateien vorhanden.")
        return

    try:
        dfs = []
        for filename in iter_with_progress(logger, matching_files, len(matching_files), "Umstellabo-Dateien laden"):
            filepath = os.path.join(UMSTELLABOS_PATH, filename)
            try:
                df = pd.read_excel(filepath, header=None)
                if df.shape[1] < 4:
                    logger.error(f"datei {filename} hat weniger als 4 Spalten.")
                    continue
                df = df.iloc[:, :4]
                df.columns = HEADERS
                df = df[df["GPNR"].astype(str).str.lower() != "umstellen"]
                df["GPNR"] = df["GPNR"].astype(str).str.ljust(10)
                df["VBELN"] = df["VBELN"].astype(str).str.zfill(10)
                df["POSNR"] = df["POSNR"].astype(str).str.zfill(6)
                dfs.append(df)
            except Exception as e:
                logger.error(f"Fehler beim Laden der datei {filename}: {e}", exc_info=True)
        if dfs:
            df = pd.concat(dfs, ignore_index=True)
        else:
            logger.error("Keine gültigen Datenframes zum Zusammenführen.")
            return
    except Exception as e:
        logger.error(f"Fehler beim Laden der Dateien: {e}", exc_info=True)
        return

    try:
        df.to_csv(temp_csv, index=False, encoding="utf-8-sig")
        import_table(os.path.abspath(temp_csv), table)
        for filename in iter_with_progress(
            logger, matching_files, len(matching_files), "Umstellabo-Dateien verschieben"
        ):
            try:
                filepath = os.path.join(UMSTELLABOS_PATH, filename)
                os.rename(filepath, os.path.join(UMSTELLABOS_BEARBEITET_PATH, filename))
                logger.info(f"datei {filename} erfolgreich verschoben")
            except Exception as e:
                logger.error(f"Fehler beim Verschieben der datei {filename}: {e}", exc_info=True)
    except Exception as e:
        logger.error(f"Fehler beim Import: {e}", exc_info=True)
        return
    finally:
        if os.path.exists(temp_csv):
            os.remove(temp_csv)
            logger.info("Temporäre datei gelöscht.")

    headers, resthost = _get_prod_api_config()
    url_base = resthost + "accounts/"
    query_text = get_query_text("UMSTELLABOS")
    df = execute_dataframe_query(query_text)

    connection = connect_to_db()
    try:
        cursor = connection.cursor()
        for index, row in iter_with_progress(logger, df.iterrows(), len(df), "Umstellabo-Subscriptions"):
            time.sleep(0.01)
            accountid = str(row.get("ACCOUNTID"))
            subscriptionid = str(row.get("SUBSCRIPTIONID"))
            posnr = str(row.get("POSNR"))
            vbeln = str(row.get("VBELN"))
            posex = str(row.get("POSEX"))
            bezirk = str(row.get("BEZIRK"))
            url = url_base + accountid + "/subscriptions/" + subscriptionid
            logger.debug(f"Verarbeite Index {index}: Account {accountid}, Subscription {subscriptionid}")

            data = [
                {"op": "replace", "path": "/CustomSubscriptionParameter/POSNR", "value": posnr},
                {"op": "replace", "path": "/CustomSubscriptionParameter/VBELN", "value": vbeln},
                {"op": "replace", "path": "/CustomSubscriptionParameter/POSEX", "value": posex},
                {"op": "replace", "path": "/CustomSubscriptionParameter/Bezirk", "value": bezirk},
                {"op": "replace", "path": "/CustomSubscriptionParameter/SendNotification", "value": "1"},
            ]
            json_data = json.dumps(data)

            try:
                response = retry_request("PATCH", url, data=json_data, headers=headers, verify=False)
                if response and response.status_code == 200:
                    cursor.execute(
                        "UPDATE tb_umstellabos SET ANGEPASST = 'Ja' WHERE VBELN = ? AND POSNR = ?", (vbeln, posnr)
                    )
                    connection.commit()
                    logger.debug(f"API-Aufruf erfolgreich für Account {accountid}")
                else:
                    status = response.status_code if response else "Keine Antwort"
                    text = response.text if response else ""
                    logger.warning(f"Fehler bei API-Aufruf für Account {accountid}: {status} - {text}")
            except requests.exceptions.RequestException as e:
                logger.error(f"API-Aufruf fehlgeschlagen für Account {accountid}: {e}", exc_info=True)
    finally:
        connection.close()

    try:
        logger.info("Führe Abfrage aus und exportiere")
        export_dir = UMSTELLABOS_PRUEF_PATH
        if matching_files:
            base_name = os.path.splitext(matching_files[0])[0]
            output = base_name
        else:
            output = "umstellabos_export"
        export_file = os.path.join(export_dir, f"{output}.xlsx")
        export_query = get_query_text("UMSTELLABOS_EXPORT")
        datenbankabfrage_mit_export(export_query, output, export_dir, "Excel")
        try:
            os.startfile(export_file)
        except Exception as e:
            logger.error(f"Fehler beim Öffnen der Exportdatei: {e}", exc_info=True)
    except Exception as e:
        logger.error(f"Fehler bei Abfrage: {e}", exc_info=True)


def run_fulfilment_move_batch() -> pd.DataFrame:
    """Führt Fulfilment-Moves für alle relevanten Tage aus.

    Returns:
        pd.DataFrame: DataFrame mit Ausführungsstatistiken.
    """
    headers, resthost = _get_prod_api_config()
    total_to_update = 0
    successful_updates = 0

    df_moves = execute_dataframe_query(get_query_text("GET_FULFILMENT_MOVE_DATES"))
    logger.info(f"Anzahl der zu verarbeitenden Tage: {len(df_moves)}")

    def extract_date(date_str: str) -> str | None:
        """Extrahiert das Datumssegment aus einem eSuite-Zeitstempel."""
        if date_str and isinstance(date_str, str):
            return date_str.split("T")[0]
        return None

    def process_fulfilment_for_day(row: pd.Series[Any]) -> None:
        """Verschiebt alle Fulfilments fuer ein einzelnes Move-Datum."""
        nonlocal total_to_update, successful_updates
        move_date_from = row["move_from"]
        move_date_to = row["move_to"]
        logger.info(f"Fulfilment-Moves werden ausgeführt für {move_date_from}")

        query = get_query_text("PROCESS_FULFILMENT_MOVE_DATES").format(
            MOVE_DATE_FROM=move_date_from, MOVE_DATE_TO=move_date_to
        )
        df = execute_dataframe_query(query)
        total_to_update += len(df)

        for _, sub_row in iter_with_progress(logger, df.iterrows(), len(df), f"Fulfilment-Abos fuer {move_date_from}"):
            accountid = str(sub_row["AccountID"])
            subscriptionid = str(sub_row["SubscriptionId"])
            subscription_reference_db = convert_id("PROD", subscriptionid, "S")
            url = resthost + "accounts/" + accountid + "/fulfilments"

            try:
                response = retry_request("GET", url, headers=headers, verify=False)
            except requests.exceptions.RequestException as e:
                logger.error(f"Fehler bei der Anfrage für AccountID {accountid}: {e}")
                continue

            if response is None:
                logger.error(f"Keine Antwort vom Server für AccountID {accountid}.")
                continue

            if response.status_code != 200:
                logger.error(f"Fehler: status Code {response.status_code}, Antwort: {response.text}")
                continue

            try:
                fulfilment_data = response.json()
                if not isinstance(fulfilment_data, list):
                    logger.warning(f"Erwartete Liste, aber etwas anderes erhalten: {type(fulfilment_data)}")
                    continue

                for item in fulfilment_data:
                    fulfilment_date = extract_date(item.get("fulfilmentDate"))
                    subscription_reference_api = item.get("subscriptionReference")
                    fulfilment_reference = item.get("fulfilmentReference")

                    if subscription_reference_api == subscription_reference_db and fulfilment_date == str(
                        move_date_from
                    ):
                        patch_url = url + "/" + fulfilment_reference
                        new_date = f"{move_date_to}T00:00:00"
                        data = [
                            {"op": "replace", "path": "/fulfilmentDate", "value": new_date},
                            {"op": "replace", "path": "/supplierNotificationDate", "value": new_date},
                        ]

                        try:
                            patch_response = retry_request(
                                "PATCH", patch_url, data=json.dumps(data), headers=headers, verify=False
                            )
                            if patch_response is None:
                                logger.error(
                                    "Keine Antwort beim PATCH für fulfilmentReference %s, überspringe.",
                                    fulfilment_reference,
                                )
                                continue

                            try:
                                log_connection = connect_to_db()
                                try:
                                    log_cursor = log_connection.cursor()
                                    log_cursor.execute(
                                        (
                                            "INSERT INTO tb_fulfilment_move_log "
                                            "(subscriptionid, move_from, move_to, bearbeitet_am) "
                                            "VALUES (?, ?, ?, CURDATE())"
                                        ),
                                        (subscriptionid, str(move_date_from), str(move_date_to)),
                                    )
                                    log_connection.commit()
                                finally:
                                    log_connection.close()
                            except Exception as e:
                                logger.error(f"Fehler beim Eintragen in tb_fulfilment_move_log: {e}")

                            successful_updates += 1

                        except Exception as e:
                            logger.error(f"Fehler beim PATCH für fulfilmentReference {fulfilment_reference}: {e}")

            except ValueError as e:
                logger.error(f"Fehler beim Parsen von JSON für AccountID {accountid}: {e}")

    for _, row in iter_with_progress(logger, df_moves.iterrows(), len(df_moves), "Fulfilment-Move-Tage"):
        process_fulfilment_for_day(row)

    logger.info(f"Gesamt: {successful_updates} von {total_to_update} Fulfilments erfolgreich aktualisiert.")

    return pd.DataFrame(
        [
            {
                "successful_updates": successful_updates,
                "total_to_update": total_to_update,
                "execution_time": datetime.now(),
                "execution_id": int(datetime.now().timestamp()),
            }
        ]
    )


def missing_vbeln_email() -> pd.DataFrame:
    """Exportiert aktive Print-Abonnements ohne VBELN als Excel-datei und versendet diese per E-Mail.

    Führt eine SQL-Abfrage auf dbm_lesermarkt aus, um Abonnements mit fehlendem VBELN
    (Wert 'leer' oder '-') zu ermitteln. Das Ergebnis wird als .xlsx-datei im konfigurierten
    Exportverzeichnis (FEHLENDE_VBELN_PATH) gespeichert und anschließend per E-Mail versandt.
    """

    query = get_query_text("MISSING_VBELN")
    export_dir = FEHLENDE_VBELN_PATH
    output = f"{datetime.now().strftime('%Y-%m-%d_%H-%M-%S')}_fehlende_vbeln"
    logger.info(f"Starte Export fehlender VBELN nach: {export_dir}/{output}.xlsx")

    df_check = execute_dataframe_query(query)
    if df_check.empty:
        logger.info("Keine Abonnements mit fehlenden VBELN gefunden.")
        now = datetime.now()
        return pd.DataFrame(
            [
                {
                    "status": "keine Einträge",
                    "execution_time": now,
                    "execution_id": int(now.timestamp()),
                }
            ]
        )

    datenbankabfrage_mit_export(query, output, export_dir, "Excel")

    export_file = os.path.join(export_dir, f"{output}.xlsx")
    attachments: list[str | Path] = [export_file] if os.path.exists(export_file) else []
    if not attachments:
        logger.warning(f"Exportdatei nicht gefunden, E-Mail wird ohne Anhang versendet: {export_file}")
    body = f"<p>Im Anhang die Liste der Abos mit fehlenden VBELN (Stand: {datetime.now().strftime('%d.%m.%Y')}).</p>"

    sender = os.environ.get("NOTIFICATION_SENDER", "")
    recipients_raw = RECIPTENTS_FEHLENDE_VBELN
    recipients = [r.strip() for r in recipients_raw.split(",") if r.strip()]

    mailer = mailer_from_encrypted_env(
        sender=sender,
        default_recipients=recipients,
    )

    now = datetime.now()

    try:
        mailer.send(
            subject=output,
            body=body,
            body_type="HTML",
            attachments=attachments,
        )
        logger.info(f"E-Mail mit fehlenden VBELN erfolgreich versendet an: {', '.join(recipients)}")
        email_status = "verschickt"
    except Exception as e:
        logger.error(f"E-Mail mit fehlenden VBELN konnte nicht versendet werden: {e}", exc_info=True)
        email_status = "nicht verschickt"
    return pd.DataFrame(
        [
            {
                "status": email_status,
                "execution_time": now,
                "execution_id": int(now.timestamp()),
            }
        ]
    )


def fcd_check() -> pd.DataFrame:
    """Überprüft FutureCancellationDate-Felder und exportiert ungültige Werte."""
    query_FCD = get_query_text("FCD_CHECK")
    df = execute_dataframe_query(query_FCD)

    if df.empty:
        logger.info("Keine ungültigen FutureCancellationDate-Werte gefunden.")
        now = datetime.now()
        return pd.DataFrame(
            [
                {
                    "status": "keine Einträge",
                    "execution_time": now,
                    "execution_id": int(now.timestamp()),
                }
            ]
        )

    logger.info(
        "%s Subscriptions mit ungültigen FutureCancellationDate-Werten gefunden. Exportiere Ergebnisse.",
        len(df),
    )
    export_dir = FALSCHE_FCD_PATH
    output = f"{datetime.now().strftime('%Y-%m-%d_%H-%M-%S')}_falsche_FCD"
    datenbankabfrage_mit_export(query_FCD, output, export_dir, "Excel")

    folder_display = export_dir.split("anzeigen", 1)[-1]
    folder_display = "anzeigen" + folder_display.replace("/", "\\")
    body = (
        "<p>Im Ordner</p>"
        f"<p>{folder_display}</p>"
        "<p>liegt die Liste der Abos mit falschen FutureCancellationDate-Werten "
        f"(Stand: {datetime.now().strftime('%d.%m.%Y')}).</p>"
    )

    sender = os.environ.get("NOTIFICATION_SENDER", "")
    recipients_raw = RECIPTENTS_FEHLENDE_FCD
    recipients = [r.strip() for r in recipients_raw.split(",") if r.strip()]

    mailer = mailer_from_encrypted_env(
        sender=sender,
        default_recipients=recipients,
    )
    now = datetime.now()
    try:
        mailer.send(
            subject=f"{len(df)} Subscriptions mit falschen FutureCancellationDate-Werten gefunden",
            body=body,
            body_type="HTML",
        )
        logger.info(
            f"E-Mail mit falschen FutureCancellationDate-Werten erfolgreich versendet an: {', '.join(recipients)}"
        )
        fcd_check_status = "verschickt"
    except Exception as e:
        logger.error(
            f"E-Mail mit falschen FutureCancellationDate-Werten konnte nicht versendet werden: {e}", exc_info=True
        )
        fcd_check_status = "nicht verschickt"
    return pd.DataFrame(
        [
            {
                "status": fcd_check_status,
                "execution_time": now,
                "execution_id": int(now.timestamp()),
            }
        ]
    )


def renewal_verschiebung() -> pd.DataFrame:
    """Verschiebt Renewal-Termine für die von der Datenbankabfrage ermittelten Subscriptions.

    Liest die Abfrage ``RENEWAL_VERSCHIEBUNG`` und aktualisiert abhängig vom
    Subscription-Typ das ExpiryDate sowie bei verknüpften Subscriptions auch
    das StartDate über die eSuite-API. Zwischen API-Aufrufen wird eine kurze
    Pause eingehalten, um die Schnittstelle zu entlasten.

    Returns:
        DataFrame mit Ausführungs-ID sowie Anzahl der gefundenen, erfolgreichen
        und fehlgeschlagenen Aktualisierungen.
    """

    API_DELAY_SECONDS = 0.5  # Verzögerung von 0.5 Sekunden zwischen den API-Aufrufen, um die Last zu reduzieren
    QUERY_RENEWAL_VERSCHIEBUNG = "RENEWAL_VERSCHIEBUNG"

    query_FCD = get_query_text(QUERY_RENEWAL_VERSCHIEBUNG)
    df = execute_dataframe_query(query_FCD)

    print(df)
    successful_updates = 0
    failed_updates = 0
    total_to_update = len(df)
    now = datetime.now()

    if df.empty:
        logger.info("Keine Subscriptions zur Verschiebung gefunden.")
        return pd.DataFrame(
            [
                {
                    "status": "keine Einträge",
                    "successful_updates": successful_updates,
                    "failed_updates": failed_updates,
                    "total_to_update": total_to_update,
                    "execution_time": now,
                    "execution_id": int(now.timestamp()),
                }
            ]
        )
    logger.info(
        "%s Subscriptions mit bevorstehenden Renewel-Terminen gefunden. Verschiebe Termine.",
        len(df),
    )
    headers, resthost = _get_prod_api_config()

    for _index, row in iter_with_progress(logger, df.iterrows(), len(df), "Renewal-Verschiebungen"):
        accountid = str(row["accountid"])
        subscriptionid = str(row["subscriptionid"])
        typ = str(row["typ"])
        url = resthost + "accounts/" + accountid + "/subscriptions/" + subscriptionid

        ts_new_expiry_basis = pd.Timestamp(row["neues_datum"]).tz_localize("Europe/Berlin")
        new_expiry_basis = ts_new_expiry_basis.tz_convert("UTC").strftime("%Y-%m-%dT%H:%M:%SZ")
        new_start_basis = ts_new_expiry_basis.tz_convert("UTC").strftime("%Y-%m-%dT%H:%M:%SZ")

        time.sleep(API_DELAY_SECONDS)  # Kurze Pause zwischen den API-Aufrufen, um die Last zu reduzieren
        if typ == "basis":
            data = [
                {"op": "replace", "path": "/ExpiryDate", "value": new_expiry_basis},
            ]
        elif typ == "verknuepft":
            ts_new_expiry_verknuepft = pd.Timestamp(row["neues_serviceexpiry"]).tz_localize("Europe/Berlin")
            new_expiry_verknuepft = ts_new_expiry_verknuepft.tz_convert("UTC").strftime("%Y-%m-%dT%H:%M:%SZ")
            data = [
                {"op": "replace", "path": "/StartDate", "value": new_start_basis},
                {"op": "replace", "path": "/ExpiryDate", "value": new_expiry_verknuepft},
            ]
        try:
            response = retry_request("PATCH", url, data=json.dumps(data), headers=headers, verify=False)
            if response and response.status_code == 200:
                logger.info(f"Renewal-Verschiebung erfolgreich für Account {accountid}")
                successful_updates += 1
            else:
                status = response.status_code if response else "Keine Antwort"
                text = response.text if response else ""
                logger.warning(f"Fehler bei Renewal-Verschiebung für Account {accountid}: {status} - {text}")
                failed_updates += 1
        except requests.exceptions.RequestException as e:
            logger.error(f"Renewal-Verschiebung fehlgeschlagen für Account {accountid}: {e}", exc_info=True)
            failed_updates += 1

    return pd.DataFrame(
        [
            {
                "status": "Verschiebung abgeschlossen",
                "successful_updates": successful_updates,
                "failed_updates": failed_updates,
                "total_to_update": total_to_update,
                "execution_time": now,
                "execution_id": int(now.timestamp()),
            }
        ]
    )


def rechnungsdruck_check() -> pd.DataFrame:
    """Prüft die Subscriptions auf falschen Rechnungsdruck und exportiert die Ergebnisse."""

    API_DELAY_SECONDS = 0.5  # Verzögerung von 0.5 Sekunden zwischen den API-Aufrufen, um die Last zu reduzieren
    QUERY_RECHNUNGSDRUCK_CHECK = "RECHNUNGSDRUCK_CHECK"

    query = get_query_text(QUERY_RECHNUNGSDRUCK_CHECK)
    df = execute_dataframe_query(query)

    successful_updates = 0
    failed_updates = 0
    total_to_update = len(df)
    now = datetime.now()

    if df.empty:
        logger.info("Keine Subscriptions mit falschem Rechnungsdruck gefunden.")
        return pd.DataFrame(
            [
                {
                    "status": "keine Einträge",
                    "successful_updates": successful_updates,
                    "failed_updates": failed_updates,
                    "total_to_update": total_to_update,
                    "execution_time": now,
                    "execution_id": int(now.timestamp()),
                }
            ]
        )
    logger.info(
        "%s Subscriptions mit falschem Rechnungsdruck gefunden. Exportiere Ergebnisse.",
        len(df),
    )
    headers, resthost = _get_prod_api_config()

    for _index, row in iter_with_progress(logger, df.iterrows(), len(df), "Rechnungsdruck-Prüfungen"):
        accountid = str(row["accountid"])
        subscriptionid = str(row["subscriptionid"])
        rechnungsdruck = str(row["rechnungsdruck"])
        url = resthost + "accounts/" + accountid + "/subscriptions/" + subscriptionid


        time.sleep(API_DELAY_SECONDS)  # Kurze Pause zwischen den API-Aufrufen, um die Last zu reduzieren

        data = [
            {"op": "replace", "path": "/CustomSubscriptionParameter/POSNR", "value": rechnungsdruck},
        ]
        try:
            response = retry_request("PATCH", url, data=json.dumps(data), headers=headers, verify=False)
            if response and response.status_code == 200:
                logger.info(f"Rechnungsdruck-Prüfung erfolgreich für Account {accountid}")
                successful_updates += 1
            else:
                status = response.status_code if response else "Keine Antwort"
                text = response.text if response else ""
                logger.warning(f"Fehler bei Rechnungsdruck-Prüfung für Account {accountid}: {status} - {text}")
                failed_updates += 1
        except requests.exceptions.RequestException as e:
            logger.error(f"Rechnungsdruck-Prüfung fehlgeschlagen für Account {accountid}: {e}", exc_info=True)
            failed_updates += 1

    return pd.DataFrame(
        [
            {
                "status": "Rechnungsdruck-Prüfung abgeschlossen",
                "successful_updates": successful_updates,
                "failed_updates": failed_updates,
                "total_to_update": total_to_update,
                "execution_time": now,
                "execution_id": int(now.timestamp()),
            }
        ]
    )

